mapper.select:
SELECT cr.id, cr.patient_id AS patient_id, d.name AS doctor_name, dept.name AS department_name, cr.ended_at AS completed_at, cr.updated_at FROM consult_record cr JOIN doctor d ON d.id = cr.doctor_id LEFT JOIN department dept ON dept.id = d.dept_id WHERE cr.patient_id = #{patientId} AND cr.status = 'COMPLETED' AND cr.doctor_note IS NOT NULL AND btrim(cr.doctor_note) != '' AND cr.deleted_at IS NULL
AND cr.ended_at >= #{completedSince}
ORDER BY cr.ended_at DESC NULLS LAST, cr.id DESC LIMIT #{limit} OFFSET #{offset}

SELECT id, patient_id, drug_name_snapshot AS drug_name, dosage, frequency, next_remind_at, reminder_enabled, reminder_times::text AS reminder_times_json, status FROM medication_plan WHERE patient_id = #{patientId} AND deleted_at IS NULL
AND status = #{status}
ORDER BY next_remind_at ASC NULLS LAST, id ASC

mapper.update:
UPDATE medication_plan
SET status         = #{status},
    next_remind_at = #{nextRemindAt},
    reminder_enabled = #{reminderEnabled},
    reminder_times = CAST(#{reminderTimesJson, jdbcType=VARCHAR} AS jsonb),
    end_at         = #{endAt},
    updated_at     = #{now}
WHERE id = #{planId}
  AND patient_id = #{patientId}

  AND status = #{expectedStatus}
  AND deleted_at IS NULL

mapper.select:
SELECT id, patient_id, follow_up_type AS type, due_at, content, status, remind_at FROM follow_up_plan WHERE patient_id = #{patientId} AND deleted_at IS NULL
AND status = #{status}
ORDER BY due_at ASC, id ASC

mapper.update:
UPDATE follow_up_plan
SET status     = 'CONFIRMED',
    remind_at  = #{remindAt},
    updated_at = #{now}

WHERE id = #{followUpId}
  AND patient_id = #{patientId}
  AND status = 'PENDING_CONFIRM'
  AND deleted_at IS NULL
